{
  "fields": {
    "unit": {
      "value": "patient_regimen",
      "evidence": [
        "article:p27",
        "supp/Sheet1/A3"
      ],
      "explanation": "The study compares drug sensitivity of organoids to clinical response for specific patient-regimen pairs. The unit is the patient-drug combination."
    },
    "platform": {
      "value": "microwell",
      "evidence": [
        "article:p14",
        "article:p1"
      ],
      "explanation": "The study uses an 'integrated superhydrophobic microwell array chip (InSMAR-chip)'."
    },
    "readout": {
      "value": "viability",
      "evidence": [
        "article:p16",
        "article:p49"
      ],
      "explanation": "Cell viability is measured using alamarBlue (AB) assay, calculated as relative viability after drug treatment compared to control."
    },
    "direction": {
      "value": "lower_sensitive",
      "evidence": [
        "article:p20",
        "article:p25"
      ],
      "explanation": "Lower viability or lower AUC indicates higher sensitivity."
    },
    "threshold_rule": {
      "value": "categorical",
      "evidence": [
        "article:p27",
        "supp/Sheet1/I3"
      ],
      "explanation": "The authors report 100% accuracy and specificity based on a binary classification of clinical response matching organoid sensitivity. The specific numeric cutoff is not explicitly defined in the text for the aggregate metric."
    },
    "threshold_timing": {
      "value": "not_reported",
      "evidence": [
        "article:p27"
      ],
      "explanation": "The paper states 100% accuracy/specificity but does not report the specific numeric viability threshold used to binarize the organoid response for this calculation."
    },
    "patient_mapping": {
      "value": "individual_available",
      "evidence": [
        "supp/Sheet1/A3",
        "supp/Sheet1/M3"
      ],
      "explanation": "Supplementary Data 2 links individual patient IDs to specific agents tested and clinical responses."
    },
    "regimen_match": {
      "value": "matched",
      "evidence": [
        "article:p25",
        "supp/Sheet1/F3"
      ],
      "explanation": "The drugs tested on organoids match the systemic treatments received by the patients."
    },
    "n_units": {
      "value": 10,
      "evidence": [
        "article:p27"
      ],
      "explanation": "Article p27 states: 'In ten of the organoid lines... the 1-week drug sensitivity results were in great agreement with the clinical data'."
    },
    "split": {
      "value": "same_cohort",
      "evidence": [
        "article:p20",
        "article:p27"
      ],
      "explanation": "The clinical comparison is performed on the same set of patients from whom the organoids were derived."
    }
  },
  "headline": {
    "metric": "accuracy",
    "reported": 1.0,
    "reported_evidence": [
      "article:p27"
    ],
    "threshold": null,
    "op": "==",
    "score_direction": "higher",
    "tolerance": 0.005,
    "records": [],
    "blocked_reason": "Source tables (Supp Sheet1) provide clinical truth (Response) and list of agents tested, but do not contain the numeric organoid sensitivity scores (e.g., AUC, IC50, or % Viability) for the specific patient-regimen pairs required to reconstruct the binary predictions. The numeric scores are present in figures (e.g., Fig 5, 6) which are not supplied as extractable data tables. Therefore, the records list cannot be populated with VALUE_SPEC for scores."
  },
  "notes": [
    "The paper reports 100% accuracy and specificity for 10 patient-regimen pairs.",
    "The specific numeric viability threshold used to classify organoids as 'sensitive' or 'resistant' is not explicitly stated in the text for the aggregate metric.",
    "Supplementary Data 2 lists the clinical outcomes and agents tested, but lacks the corresponding quantitative organoid assay results (scores) needed to verify the binary classification logic.",
    "Previous error arose from attempting to parse the list of agents ('PC GC DC...') as numeric scores. The correct action is to block record generation due to missing numeric score evidence in the supplied tables."
  ]
}
